"""P24 stage A: run ONE verify step alone and print its process's peak RSS (bytes, macOS)."""
import json, resource, sys
from pathlib import Path

if __name__ == "__main__":
    step, source, store = sys.argv[1], Path(sys.argv[2]), Path(sys.argv[3])
    from sdip.cli.main import _declaration
    declaration = _declaration("1", "PostStack3DTime", None, None)
    if step == "baseline":
        pass
    elif step == "binding":
        from sdip.equivalence.binding import check_binding; check_binding(store, declaration)
    elif step == "preflight":
        from sdip.ingest.orchestrator import validate_source; validate_source(source, declaration)
    elif step == "g1":
        from sdip.spec import g1_for_spec; g1_for_spec(declaration.build_spec())
    elif step.startswith("plane_"):
        from sdip.equivalence import plane_1, plane_2, plane_3, plane_4, plane_5
        from sdip.spec import g1_for_spec
        built = declaration.build_spec(); spec = built.segy_spec
        n = int(step[-1])
        if n == 1: plane_1(source, store)
        elif n == 2: plane_2(source, store, declaration=declaration)
        elif n == 3: plane_3(source, store, spec, g1_passed=g1_for_spec(built).passed)
        elif n == 4: plane_4(source, store, spec)
        else: plane_5(source, store, spec)
    elif step == "trace_map":
        from segy import SegyFile
        from sdip.equivalence.planes import _open_store, grid_coordinates, store_dimensions
        from sdip.equivalence.trace_map import build_trace_map
        spec = declaration.build_spec().segy_spec
        headers = SegyFile(str(source), spec=spec).header[:]
        group = _open_store(store); dims = store_dimensions(group)
        build_trace_map(headers, grid_coordinates(group, dims), dims)
    elif step == "store_digest":
        from sdip.provenance.store_digest import check_store_digest; check_store_digest(store)
    elif step == "content_digest":
        from sdip.provenance.store_digest import check_content_digest; check_content_digest(store)
    else:
        raise SystemExit(f"unknown step {step}")
    print(json.dumps({"step": step, "ru_maxrss": resource.getrusage(resource.RUSAGE_SELF).ru_maxrss}))
